@import url('https://fonts.googleapis.com/css2?family=Khand:wght@400;500;600;700&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Arsenal DNA — cannon red blocks, white sleeves, north london navy */
.theme-arsenal {
  --bg: oklch(1.000 0 0);
  --surface: oklch(0.973 0 0);
  --surface-2: oklch(0.946 0 0);
  --fg: oklch(0.130 0.054 275.9);
  --fg-muted: oklch(0.529 0.022 285.6);
  --accent: oklch(0.419 0.168 27.4);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.697 0.135 231.6);
  --line: oklch(0.910 0 0);
  --success: oklch(0.523 0.135 144.2);
  --warning: oklch(0.768 0.158 81.3);
  --danger: oklch(0.55 0.2 27);
  --radius: 0.25rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Khand", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: uppercase;
  --label-tracking: 0.1em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-arsenal h1,
.theme-arsenal h2,
.theme-arsenal h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-arsenal { --font-ui: var(--font-display); }
.theme-arsenal h1, .theme-arsenal h2 { text-transform: uppercase; }
.theme-arsenal button { text-transform: uppercase; letter-spacing: 0.06em; }

.theme-arsenal h2 { border-left: 6px solid var(--accent); padding-left: 0.6rem; }
.theme-arsenal button { border-radius: 0; }
.theme-arsenal ::selection { background: var(--accent-2); color: #04041c; }

/* depth */
.theme-arsenal thead th { background: var(--accent); color: oklch(1 0 0); text-transform: uppercase; letter-spacing: 0.08em; font-size: 0.78em; }
.theme-arsenal td { border-bottom: 1px solid var(--line); }
.theme-arsenal tbody tr:hover { background: oklch(0.419 0.168 27.4 / 7%); }
.theme-arsenal a { color: var(--accent); text-underline-offset: 3px; text-decoration-thickness: 2px; }
.theme-arsenal a:hover { color: oklch(0.130 0.054 275.9); text-decoration-color: var(--accent); }
.theme-arsenal ::selection { background: var(--accent); color: oklch(1 0 0); }
.theme-arsenal input, .theme-arsenal select, .theme-arsenal textarea { border-radius: 0; }
.theme-arsenal input:focus-visible, .theme-arsenal select:focus-visible, .theme-arsenal textarea:focus-visible { outline: 2px solid var(--accent); outline-offset: 0; }
.theme-arsenal kbd { background: oklch(1 0 0); border: 1px solid oklch(0.130 0.054 275.9); border-bottom-width: 3px; border-radius: 0; padding: 0.1em 0.45em; font-family: var(--font-mono); }
.theme-arsenal ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-arsenal ::-webkit-scrollbar-track { background: var(--surface-2); }
.theme-arsenal ::-webkit-scrollbar-thumb { background: var(--accent); border-radius: 0; }
.theme-arsenal ::-webkit-scrollbar-thumb:hover { background: oklch(0.130 0.054 275.9); }
.theme-arsenal .label-caps { color: var(--accent); }
/* white sleeves: hover inverts the shirt */
.theme-arsenal button:hover { background: oklch(1 0 0); color: var(--accent); box-shadow: inset 0 0 0 2px var(--accent); }
.theme-arsenal .themed-border { border-left: 6px solid var(--accent); }

/* alt mode: away kit (2026-27 real kit / NBA Association Edition) */
.theme-arsenal.alt-mode {
  --bg: oklch(0.193 0.062 265.4);
  --surface: oklch(0.237 0.072 264.5);
  --surface-2: oklch(0.284 0.076 262.9);
  --fg: oklch(0.944 0.028 95.9);
  --fg-muted: oklch(0.722 0.048 271.5);
  --accent: oklch(0.846 0.156 92.7);
  --accent-fg: oklch(0.193 0.062 265.4);
  --accent-2: oklch(0.598 0.245 28.8);
  --line: oklch(0.85 0.12 95 / 25%);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  background-image: repeating-linear-gradient(45deg, oklch(0.3 0.07 265 / 40%) 0 40px, transparent 40px 80px), repeating-linear-gradient(-45deg, oklch(0.85 0.14 95 / 5%) 0 24px, transparent 24px 72px);
}
.theme-arsenal.alt-mode h1, .theme-arsenal.alt-mode h2 { color: #f0c93c; border-color: #f0c93c; }
.theme-arsenal.alt-mode thead th { color: var(--accent-fg); }
.theme-arsenal.alt-mode a:hover { color: var(--accent); text-decoration-color: oklch(1 0 0 / 70%); }
.theme-arsenal.alt-mode button:hover { background: oklch(0.944 0.028 95.9); color: oklch(0.193 0.062 265.4); box-shadow: inset 0 0 0 2px oklch(0.193 0.062 265.4); }
.theme-arsenal.alt-mode kbd { background: var(--accent); color: var(--accent-fg); border-color: var(--accent-fg); }
.theme-arsenal.alt-mode ::-webkit-scrollbar-thumb:hover { background: var(--fg); }
.theme-arsenal.alt-mode tbody tr:hover { background: oklch(0.846 0.156 92.7 / 10%); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"], [class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
